USE CordobaMascotas;
GO

-- Fotos para las publicaciones 1 a 5, que tenian texto de relleno (foto-luna, foto-toby, ...)
-- en lugar de una imagen. Cada UPDATE solo actua si la foto sigue siendo ese texto,
-- asi no pisa una imagen cargada despues desde la aplicacion.
--
-- Imagenes de Wikimedia Commons (https://commons.wikimedia.org), reducidas a 960 px de ancho:
--   1 Luna   File:Labrador Retriever yellow portrait.jpg - Franca from Le Muids, Switzerland - CC BY 2.0
--   2 Toby   File:Urban Dog Portrait (49767129888).jpg - Reba Spike - CC BY 2.0
--   3 Michi  File:Siamese-Cat Andreas-LischkaPixabay.jpg - webandi (Andreas Lischka) - CC0
--   4 Rocky  File:Brown street dog 02.jpg - A S M Jobaer - CC BY-SA 4.0
--   5 Bruno  File:Mongrel Dog Cosimo.jpg - Claudia Krebs - CC BY 2.5

SET XACT_ABORT ON;
BEGIN TRANSACTION;

-- 1: Luna
UPDATE publicaciones_adopcion
SET foto = 
WHERE nro_publicacion = 1 AND foto = 0x666F746F2D6C756E61;

-- 2: Toby
UPDATE publicaciones_adopcion
SET foto = 
WHERE nro_publicacion = 2 AND foto = 0x666F746F2D746F6279;

-- 3: Michi
UPDATE publicaciones_adopcion
SET foto = 
WHERE nro_publicacion = 3 AND foto = 0x666F746F2D6D69636869;

-- 4: Rocky
UPDATE publicaciones_adopcion
SET foto = 
WHERE nro_publicacion = 4 AND foto = 0x666F746F2D726F636B79;

-- 5: Bruno
UPDATE publicaciones_adopcion
SET foto = 
WHERE nro_publicacion = 5 AND foto = 0x666F746F2D6E75657661;

COMMIT TRANSACTION;
GO

